head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil51500";
scwin.upd_fncContnAttachExcelfile = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.upd_fncContnAttachExcelfile = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_fncContnAttachExcelfile') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_fncContnAttachExcelfile"]');
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil51500.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_excelUpload_onclick
 * @description 「파일 선택」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_excelUpload_onclick = async function(e){
    try {
        await scwin.excelUpload()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil51500.btn_excelUpload_onclick' }); }
};

/**
 * @method
 * @name btn_window_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_window_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil51500.btn_window_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_excelUpload
 * @description excel Upload 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_excelUpload = async function () {
    const sbmOptions = {
        id: "tx_fn_excelUpload",
        method: "post",
        action: "/listInvstg/listPrelmInvstg.do?method=fncContnExcelUploadData",
        ref: "dma_excelUploadReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name excelUpload
 * @description excel Upload 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelUpload = async function () {
    if (($c.util.getComponent('upd_fncContnAttachExcelfile').getValue() == null ? '' : String($c.util.getComponent('upd_fncContnAttachExcelfile').getValue())) === '') {
        await $c.win.alert("파일을 선택하세요.");
        return;
    } else {
        if (!scwin.checkFileType($c.util.getComponent('upd_fncContnAttachExcelfile').getValue())) {
            await $c.win.alert("엑셀파일만 업로드 가능합니다. 다시 선택하세요.");
            return;
        }
    }
    if (await $c.win.confirm("업로드 하시겠습니까?")) {
        $c.util.getComponent("dialogLoading").setStyle("display", "");
        await scwin.tx_fn_excelUpload();
    }
};

/**
 * @method
 * @name checkFileType
 * @description check File Type 처리
 * @param {*} filePath filePath
 * @returns {void}
 * @hidden N
 */
scwin.checkFileType = function (filePath) {
    const fileFormat = filePath.toLowerCase();
    if (fileFormat.indexOf(".xls") > -1) {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name setLoadDataPop
 * @description set Load Data Pop 처리
 * @param {*} dataArr dataArr
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setLoadDataPop = async function (dataArr) {
    if ((((scwin.openerScwin()) !== scwin && typeof (scwin.openerScwin()).fn_setLoadData === 'function' ? (scwin.openerScwin()).fn_setLoadData(dataArr) : void 0), $c.win.closePopup([dataArr]))) {
        await $c.win.alert('파일 업로드가 정상 처리되었습니다.\n - 항목별 값 확인 후 [저장] 버튼을 선택하세요.');
        $c.win.closePopup();
    } else {
        await $c.win.alert('재무사항 화면으로 데이터 처리시 오류가 발생했습니다.\n - 메뉴를 다시 선택하여 진행하세요.');
    }
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
